require_once __DIR__ . '/../config/database.php';if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['ok'=>false,'message'=>'Método no permitido.'],405);$u=require_login();csrf_check();$d=request_data();$id=(int)($d['id_reporte']??0);$comentario=text_input($d,'comentario',2000);$pdo=db();$q=$pdo->prepare('SELECT id_usuario FROM reportes WHERE id=?');$q->execute([$id]);$owner=$q->fetchColumn();if(!$owner)json_response(['ok'=>false,'message'=>'Reporte inexistente.'],404);if($u['rol']!=='administrador'&&(int)$owner!==(int)$u['id'])json_response(['ok'=>false,'message'=>'No tenés permiso.'],403);$q=$pdo->prepare('INSERT INTO comentarios(comentario,id_reporte,id_usuario) VALUES(?,?,?)');$q->execute([$comentario,$id,$u['id']]);json_response(['ok'=>true,'message'=>'Comentario agregado.'],201);
